using System;

namespace Game_Catalog.Models
{
    /// <summary> Represents one play session of a game. An open session has no end time. </summary>
    public class PlaySession
    {
        /// <summary> Unique identifier of the session. Generated by the database. </summary>
        public int PlaySessionId { get; set; }

        /// <summary> Identifier of the played game. </summary>
        public int GameId { get; set; }

        private string _gameTitle = string.Empty;
        /// <summary> Title of the played game, loaded together with the session. </summary>
        public string GameTitle
        {
            get => _gameTitle;
            set => _gameTitle = value ?? string.Empty;
        }

        /// <summary> Date and time the session started. </summary>
        public DateTime StartTime { get; set; }

        /// <summary> Date and time the session ended. Null while the session is still going. </summary>
        public DateTime? EndTime { get; set; }

        /// <summary> Length of the session in seconds. Computed by the database, null for an open session. </summary>
        public int? DurationSeconds { get; set; }

        /// <summary> How the session was added to the system. </summary>
        public EntryMethod EntryMethod { get; set; } = EntryMethod.Manual;

        private string _note = string.Empty;
        /// <summary> Free-form note. Empty means no note. </summary>
        public string Note
        {
            get => _note;
            set => _note = value ?? string.Empty;
        }
    }
}
